    MC_OPT_SOUNDS = "Sons de combat",
    MC_OPT_SOUNDS_TIP = "Sons de combat du jeu : chaque technique joue le son de sort ou d'arme du jeu. Sons simples : un son de coup et un son de soin pour tout.",
