    MC_Q_cairne_mulgore_1_TITLE = "Les plaines de Mulgore",
    MC_Q_cairne_mulgore_1_TEXT = "Hurans et foreurs de la KapitalRisk rôdent dans les plaines au pied des Pitons-du-Tonnerre. Avant que les tribus puissent se reposer, Mulgore doit être sûr.",
    MC_Q_cairne_mulgore_2_TITLE = "Vieux ennemis",
    MC_Q_cairne_mulgore_2_TEXT = "Les centaures kolkar chassent les taurens depuis des générations. Cairne compte leur montrer que cette époque est révolue.",
    MC_Q_cairne_mulgore_3_TITLE = "La terre tremble",
    MC_Q_cairne_mulgore_3_TEXT = "On entend de loin le choc martial d'un grand chef. Que les Tarides l'entendent souvent.",
    MC_Q_cairne_mulgore_4_TITLE = "Le chasseur de kodos",
    MC_Q_cairne_mulgore_4_TEXT = "Un chasseur des Tarides massacre les kodos sacrés des taurens. Cairne se dressera devant lui sans tomber.",
    MC_Q_bolvar_defias_1_TITLE = "Ennuis dans la forêt d'Elwynn",
    MC_Q_bolvar_defias_1_TEXT = "Gnolls et kobolds ravagent les fermes autour de Comté-de-l'Or. La garde de Hurlevent manque de bras : le généralissime s'en mêle lui-même.",
    MC_Q_bolvar_defias_2_TITLE = "La Confrérie défias",
    MC_Q_bolvar_defias_2_TEXT = "Des hommes masqués aux foulards rouges brûlent les champs de la Marche de l'Ouest. Bolvar veut les arrêter, un par un.",
    MC_Q_bolvar_defias_3_TITLE = "Le chef dans l'ombre",
    MC_Q_bolvar_defias_3_TEXT = "Chaque piste mène à l'homme derrière la confrérie. Affrontez-le dans la Marche de l'Ouest, et que le généralissime reste debout.",
    MC_Q_bolvar_defias_4_TITLE = "Sous Ruisselune",
