    MC_Q_mankrik_olgra_1_TITLE = "Sang et tonnerre",
    MC_Q_mankrik_olgra_1_TEXT = "Chaque grunt de la Horde fait d'abord ses preuves en Durotar. Mankrik ne fait pas exception.",
    MC_Q_mankrik_olgra_2_TITLE = "Les Tranchecrins",
    MC_Q_mankrik_olgra_2_TEXT = "Des pillards hurans ont attaqué les caravanes des Tarides et pris à Mankrik bien plus que de l'or.",
    MC_Q_mankrik_olgra_3_TITLE = "Vengeance",
    MC_Q_mankrik_olgra_3_TEXT = "Le chagrin a alourdi la hache de Mankrik. Que chaque coup se souvienne d'Olgra.",
    MC_Q_mankrik_olgra_4_TITLE = "Où est Olgra ?",
