    MC_Q_magni_ironforge_1_TITLE = "Le foyer du roi de la Montagne",
    MC_Q_magni_ironforge_1_TEXT = "Avant que le roi de Forgefer ne parte, ses propres vallées doivent être sûres.",
    MC_Q_magni_ironforge_2_TITLE = "Des troggs sous terre",
