    MC_Q_tirion_exile_1_TITLE = "Un chevalier sans ordre",
    MC_Q_tirion_exile_1_TEXT = "Privé de son titre, Tirion manie encore son marteau pour la Lumière.",
    MC_Q_tirion_exile_2_TITLE = "L'ombre du Fléau",
