    MC_Q_tirion_exile_3_TITLE = "Là où tout a commencé",
    MC_Q_tirion_exile_3_TEXT = "À Hautebrande, Tirion épargna jadis un orc et perdit tout. Il y retourne.",
    MC_Q_tirion_exile_4_TITLE = "La résolution de Fordring",
