    MC_Q_taelan_crusade_3_TITLE = "Terre consacrée",
    MC_Q_taelan_crusade_3_TEXT = "Là où se tient Taelan, le sol brûle pour la Lumière.",
    MC_Q_taelan_crusade_4_TITLE = "Sur les pas du père",
