    MC_Q_fandral_staghelm_4_TITLE = "Féralas envahie",
    MC_Q_fandral_staghelm_4_TEXT = "Le roi ogre de Féralas règne sur des ruines des anciens elfes. Fandral l'affrontera debout.",
