    MC_ZD_thousandneedles = "Entre las mesas, los centauros Galak asaltan las caravanas y %s reúne a su clan contra los tauren.",
    MC_ZD_alterac = "Desde las ruinas de Alterac, el Sindicato sigue conspirando, dirigido por %s, heredero del rey traidor.",
