    MC_Q_bolvar_defias_1_TITLE = "Беда в Элвиннском лесу",
    MC_Q_bolvar_defias_1_TEXT = "Гноллы и кобольды разоряют фермы вокруг Златоземья. Страже Штормграда не хватает людей, и верховный лорд берется за дело сам.",
    MC_Q_bolvar_defias_2_TITLE = "Братство Справедливости",
    MC_Q_bolvar_defias_2_TEXT = "Люди в масках и красных платках жгут поля Западного края. Болвар хочет остановить их всех до одного.",
    MC_Q_bolvar_defias_3_TITLE = "Вожак в тени",
    MC_Q_bolvar_defias_3_TEXT = "Все следы ведут к человеку, стоящему за братством. Сразитесь с ним в Западном крае, и пусть верховный лорд устоит.",
    MC_Q_bolvar_defias_4_TITLE = "Под Луноручьем",
    MC_Q_bolvar_defias_4_TEXT = "Братство не побеждено: его сердце бьется в старых шахтах под Луноручьем. Станьте достаточно сильны, чтобы последовать туда.",
    MC_Q_mankrik_olgra_1_TITLE = "Кровь и гром",
