    MC_OPT_EFFECTS = "战斗中的法术特效",
    MC_OPT_EFFECTS_TIP = "火球、寒冰箭、治疗和护盾都与游戏本身一致。关闭后恢复早期版本的简单光效。",
    MC_OPT_COLORBLIND = "色盲友好的职责颜色",
