    MC_ZD_swampofsorrows = "鱼人潜伏在泥沼中，而在阿塔哈卡神庙的沉没废墟里，%s散播着梦魇。",
    MC_ZD_dustwallow = "黑龙族在沼泽中集结。在她的巢穴里，死亡之翼之女%s等待着勇者。",
    MC_ZD_feralas = "戈杜尼食人魔统治着埃尔德拉斯的废墟，而在厄运之槌，%s坐在他的王座上。",
    MC_ZD_tanaris = "强盗、海盗和沙怒巨魔肆虐沙漠。在祖尔法拉克，九头蛇%s从圣池中升起。",
    MC_ZD_hinterlands = "邪枝巨魔占据着辛特兰的金萨洛尔，%s在那里召唤黑暗之神。",
    MC_ZD_searinggorge = "黑铁矮人驱赶着奴隶穿过燃烧的峡谷，为%s效力。",
    MC_ZD_azshara = "纳迦和幽灵出没于陨落的艾萨拉海岸，而%s守护着那里的魔法。",
    MC_ZD_blastedlands = "恶魔和暗誓者在黑暗之门前集结。%s统领着燃烧军团的大军。",
    MC_ZD_felwood = "腐化的费伍德森林在加德纳尔隐藏着暗影议会，由%s统治。",
    MC_ZD_ungoro = "在蒸腾的环形山中游荡着巨兽——没有一只比%s更强大。",
    MC_ZD_burningsteppes = "黑石兽人行进在燃烧平原上，由来自黑石塔的%s率领。",
    MC_ZD_westernplaguelands = "天灾军团占据着瘟疫肆虐的田野。在通灵学院，%s教授死灵法术。",
    MC_ZD_easternplaguelands = "亡灵大军守卫着斯坦索姆的废墟，%s在那里统治。",
    MC_ZD_winterspring = "在白雪覆盖的山谷中，冬泉熊怪敌视所有外来者——率领他们的是%s。",
    MC_ZD_silithus = "异种虫群从安其拉涌出。在深处，上古之神%s蠢蠢欲动。",
    MC_ZD_hyjal = "在世界之树曾经燃烧的地方，%s依然回荡——那是陨落于海加尔山的恶魔领主。",
    MC_ZD_elwynn = "豺狼人和狗头人在宁静的森林中作乱——豺狼人%s是他们的首领。",
    MC_ZD_dunmorogh = "在丹莫罗的雪地里，穴居人和霜鬃巨魔四处游荡。地下的诺莫瑞根已落入%s之手。",
    MC_ZD_tirisfal = "亡灵在提瑞斯法林地徘徊，而由%s率领的血色十字军焚烧一切他们认为不洁的东西。",
    MC_ZD_teldrassil = "在世界之树下，堕落的生物聚集在邪火岩周围，%s在那里密谋。",
    MC_ZD_durotar = "杜隆塔尔的红色峡谷庇护着部落——还有巫医%s，他控制着回音群岛。",
    MC_ZD_mulgore = "在莫高雷的平原上，巨型科多兽%s践踏着前方的一切。",
    MC_ZD_zephras = "在云层之上，天生者之岛在%s的风暴下颤抖。",
    MC_ZD_westfall = "迪菲亚兄弟会从死亡矿井统治着西部荒野的田野。%s在下面等待。",
    MC_ZD_lochmodan = "碎石穴居人在他们的首领%s的带领下涌入洛克莫丹的山丘。",
    MC_ZD_silverpine = "狼人在银松森林中嚎叫，它们受到来自影牙城堡的%s的召唤。",
    MC_ZD_darkshore = "灰雾部族的鱼人在可怕的%s率领下劫掠黑海岸。",
    MC_ZD_barrens = "半人马和野猪人争夺尘土飞扬的贫瘠之地。%s率领着科尔卡的袭击。",
    MC_ZD_redridge = "黑石兽人和豺狼人威胁着湖畔镇。他们的督军：%s。",
    MC_ZD_stonetalon = "风险投资公司在贪婪的%s带领下砍伐石爪山脉的古老森林。",
    MC_ZD_ashenvale = "灰谷海岸之下是黑暗深渊，远古巨兽%s的巢穴。",
    MC_ZD_duskwood = "在永恒的黑夜中，暮色森林的亡灵复活了——憎恶%s正向夜色镇进军。",
    MC_ZD_wetlands = "龙喉氏族在%s的统治下占据着湿地。",
    MC_ZD_hillsbrad = "希尔斯布莱德丘陵被战火撕裂；%s竭尽全力保卫小镇。",
