    MC_Q_cairne_mulgore_3_TEXT = "酋长的战争践踏声传得很远。让贫瘠之地常常听见它。",
    MC_Q_cairne_mulgore_4_TITLE = "科多兽猎手",
    MC_Q_cairne_mulgore_4_TEXT = "贫瘠之地有个猎手在屠杀牛头人奉为神圣的科多兽。凯恩将挺身面对他，绝不倒下。",
    MC_Q_bolvar_defias_1_TITLE = "艾尔文森林的麻烦",
    MC_Q_bolvar_defias_1_TEXT = "豺狼人和狗头人肆虐闪金镇周围的农场。暴风城卫兵人手不足，大领主亲自出手相助。",
    MC_Q_bolvar_defias_2_TITLE = "迪菲亚兄弟会",
    MC_Q_bolvar_defias_2_TEXT = "戴红色头巾的蒙面人焚烧着西部荒野的田地。伯瓦尔要将他们一个个阻止。",
    MC_Q_bolvar_defias_3_TITLE = "幕后首领",
    MC_Q_bolvar_defias_3_TEXT = "所有线索都指向兄弟会背后的那个人。在西部荒野与他对决，并让大领主屹立到最后。",
    MC_Q_bolvar_defias_4_TITLE = "月溪镇之下",
    MC_Q_bolvar_defias_4_TEXT = "兄弟会并未覆灭：它的心脏在月溪镇下的旧矿井中跳动。变得足够强大，才能追随而去。",
    MC_Q_mankrik_olgra_1_TITLE = "鲜血与雷霆",
    MC_Q_mankrik_olgra_1_TEXT = "部落的每个步兵都先在杜隆塔尔证明自己。曼科里克也不例外。",
    MC_Q_mankrik_olgra_2_TITLE = "钢鬃野猪人",
    MC_Q_mankrik_olgra_2_TEXT = "野猪人劫掠者袭击了贫瘠之地的商队，从曼科里克那里夺走的远不止金子。",
    MC_Q_mankrik_olgra_3_TITLE = "复仇",
    MC_Q_mankrik_olgra_3_TEXT = "悲痛让曼科里克的斧头变得沉重。让每一击都铭记奥尔加。",
    MC_Q_mankrik_olgra_4_TITLE = "奥尔加在哪里？",
    MC_Q_mankrik_olgra_4_TEXT = "劫掠者的踪迹消失在贫瘠之地深处。曼科里克必须活着走到尽头。",
    MC_Q_shandris_sentinel_1_TITLE = "泰达希尔的哨兵",
    MC_Q_shandris_sentinel_1_TEXT = "腐化蔓延在世界之树的森林中。哨兵将军首先守护自己的家园。",
    MC_Q_shandris_sentinel_2_TITLE = "黑海岸的守望",
    MC_Q_shandris_sentinel_2_TEXT = "鱼人和熊怪逼近奥伯丁。珊蒂斯亲自前往。",
    MC_Q_shandris_sentinel_3_TITLE = "月之箭",
    MC_Q_shandris_sentinel_3_TEXT = "哨兵的箭代她发声。让它常常发声吧。",
    MC_Q_shandris_sentinel_4_TITLE = "灰谷保卫战",
    MC_Q_shandris_sentinel_4_TEXT = "灰谷边缘的沉没神殿中有东西在蠢动。珊蒂斯将直面它，屹立不倒。",
    MC_Q_benedictus_light_1_TITLE = "提瑞斯法的圣光",
    MC_Q_benedictus_light_1_TEXT = "血色十字军口称圣光，却焚烧生者与死者。大主教要亲眼看个究竟。",
    MC_Q_benedictus_light_2_TITLE = "信仰之盾",
    MC_Q_benedictus_light_2_TEXT = "圣光守护行走于其中之人。一次又一次地庇护你的同伴吧。",
    MC_Q_benedictus_light_3_TITLE = "暮色森林的黑暗",
    MC_Q_benedictus_light_3_TEXT = "亡者在暮色森林中游荡。教会无法视而不见。",
    MC_Q_benedictus_light_4_TITLE = "憎恶",
    MC_Q_benedictus_light_4_TEXT = "一个缝合怪在通往夜色镇的路上游荡。本尼迪塔斯将与它抗争到底。",
    MC_Q_hamuul_naralex_1_TITLE = "大地母亲的召唤",
    MC_Q_hamuul_naralex_1_TEXT = "德鲁伊在治愈世界之前，先要治愈家园。莫高雷为先。",
    MC_Q_hamuul_naralex_2_TITLE = "生长",
    MC_Q_hamuul_naralex_2_TEXT = "生命回应生命。让哈缪尔的回春术使同伴屹立不倒。",
    MC_Q_hamuul_naralex_3_TITLE = "扭曲的贫瘠之地",
    MC_Q_hamuul_naralex_3_TEXT = "贫瘠之地的野兽变得狂野而怪异，仿佛有什么东西把它们梦成了这样。削减它们的数量。",
    MC_Q_hamuul_naralex_4_TITLE = "纳拉雷克斯之梦",
    MC_Q_hamuul_naralex_4_TEXT = "德鲁伊纳拉雷克斯进入洞穴治愈大地，却再也没有醒来。他的梦魇正在蔓延。变得足够强大，才能追随他。",
    MC_A_rhahkzor_s = "拉克佐猛击",
    MC_A_minerjohnson_s = "撕裂",
    MC_A_sneed_s = "恐吓",
    MC_A_gilnid_s = "熔铁之水",
    MC_A_smite_s = "重拳猛击",
    MC_A_greenskin_s = "毒性鱼叉",
    MC_A_cookie_s = "烹制甜点",
    MC_ZD_deadmines = "迪菲亚兄弟会在月溪镇下的旧矿井里建造战舰。杀穿矿工、地精和海盗，直抵%s。",
    MC_DUNGEON = "地下城",
    MC_JOURNAL = "冒险指南",
    MC_JOURNAL_HIDDEN = "隐藏首领",
    MC_JOURNAL_HIDDEN_HINT = "完成%s的任务后出现。",
    MC_JOURNAL_OWNED = "已拥有：%s",
    MC_JOURNAL_FORMULAS = "每个首领都可能教会一种附魔配方（最高%d阶，英雄%d阶）。",
    MC_LOOT_FOUND = "战利品：%s",
    MC_FORMULA_LEARNT = "学会配方：%s",
    MC_QO_DUNGEON = "通关%s，队伍中需有%s。",
    MC_QUEST_UNLOCK_deadmines_johnson = "在死亡矿井中揭示矿工约翰森",
    MC_Q_bolvar_deadmines_1_TITLE = "矿工的秘密",
    MC_Q_bolvar_deadmines_1_TEXT = "矿工们低声谈论一个知道隐秘矿道的约翰森。削减下面兄弟会的人数，他就会现身。",
    MC_RESULT_TREASURES = "宝藏",
    MC_RESULT_LOOT = "战利品（在营地等待）",
    MC_ITEM_FOUND_FREE = "栏位空闲",
    MC_ITEM_FOUND_WORN_TIP = "%s当前装备：",
    MC_ITEM_FOR_SLOT = "适用于%s栏位（%s）",
    MC_ITEM_FOR_KIND = "适用于%s栏位",
    MC_ITEM_FOUND_COUNT = "%d / %d",
    MC_A_anacondra_s = "德鲁伊的睡眠",
    MC_A_pythas_s = "雷霆一击",
    MC_A_cobrahn_s = "考布莱恩毒蛇形态",
    MC_A_skum_s = "闪电链",
    MC_A_serpentis_s = "治疗之触",
    MC_A_faeriedragon_s = "催眠术",
    MC_A_verdan_s = "缠绕之藤",
    MC_A_mutanus_s = "纳拉雷克斯的梦魇",
    MC_ZD_wailing = "德鲁伊纳拉雷克斯梦想治愈贫瘠之地，却陷入梦魇。他的尖牙领主守卫着洞穴，扭曲的生物爬了出来。%s在尽头等待。",
    MC_JOURNAL_RARE = "稀有：在%d%%的探索中出现",
    MC_QK_DEVIATE = "变异生物",
    MC_QUEST_UNLOCK_wailing_mutanus = "在哀嚎洞穴中唤醒吞噬者穆坦努斯",
    MC_Q_hamuul_dream_1_TITLE = "吞噬者苏醒",
    MC_Q_hamuul_dream_1_TEXT = "每一个倒下的变异生物都会削弱梦魇的控制。当纳拉雷克斯开始苏醒，以他的梦为食的东西将会出现。",
    MC_NODE_PASS = "通道",
    MC_PASS_INFO = "绕过隐藏首领继续前进。",
    MC_QK_TROGG = "穴居人",
    MC_QK_DARKIRON = "黑铁矮人",
    MC_QK_BLACKROCK = "黑石兽人",
    MC_QK_SCARLET = "血色十字军",
    MC_QK_SYNDICATE = "辛迪加成员",
    MC_QK_OGRE = "食人魔",
    MC_QK_WORGEN = "狼人",
    MC_QK_TROLL = "巨魔",
    MC_QK_DRAGONMAW = "龙喉兽人",
    MC_QK_CROCOLISK = "鳄鱼",
    MC_QK_MURLOC = "鱼人",
    MC_QK_SATYR = "萨特",
    MC_QK_GRIMTOTEM = "恐怖图腾牛头人",
    MC_QK_FANG = "尖牙德鲁伊",
    MC_Q_magni_ironforge_1_TITLE = "山丘之王的家园",
    MC_Q_magni_ironforge_1_TEXT = "铁炉堡之王出征之前，必须先确保自己的山谷安全。",
    MC_Q_magni_ironforge_2_TITLE = "地底的穴居人",
    MC_Q_magni_ironforge_2_TEXT = "矮人挖的每一座矿里都有穴居人爬出来。麦格尼要把它们赶回去。",
    MC_Q_magni_ironforge_3_TITLE = "黑铁的威胁",
    MC_Q_magni_ironforge_3_TEXT = "黑铁氏族一直在密谋对付铁炉堡，自三锤之战以来便是如此。",
    MC_Q_magni_ironforge_4_TITLE = "龙喉兵临城下",
    MC_Q_magni_ironforge_4_TEXT = "龙喉兽人占据着湿地，那是矮人王国之间的要道。麦格尼将击败他们的首领并屹立不倒。",
    MC_Q_tirion_exile_1_TITLE = "没有骑士团的骑士",
    MC_Q_tirion_exile_1_TEXT = "失去头衔的提里奥依然为圣光挥舞战锤。",
    MC_Q_tirion_exile_2_TITLE = "天灾的阴影",
    MC_Q_tirion_exile_2_TEXT = "亡者再次行走。提里奥亲眼见过他们对洛丹伦做了什么。",
    MC_Q_tirion_exile_3_TITLE = "一切的开始",
    MC_Q_tirion_exile_3_TEXT = "提里奥曾在希尔斯布莱德放过一个兽人，并因此失去一切。他回去了。",
    MC_Q_tirion_exile_4_TITLE = "弗丁的决心",
    MC_Q_tirion_exile_4_TEXT = "老骑士的力量随每一场战斗而增长。让它成长吧。",
    MC_Q_eitrigg_oldclan_1_TITLE = "旧氏族，新道路",
    MC_Q_eitrigg_oldclan_1_TEXT = "伊崔格曾与黑石氏族并肩作战，如今他与之为敌。",
    MC_Q_eitrigg_oldclan_2_TITLE = "古老的壁垒",
    MC_Q_eitrigg_oldclan_2_TEXT = "伊崔格的盾牌之后，年轻人安然无恙。",
    MC_Q_eitrigg_oldclan_3_TITLE = "燃烧的赤脊山",
    MC_Q_eitrigg_oldclan_3_TEXT = "赤脊山的黑石首领必须倒下，伊崔格要站着见证这一刻。",
    MC_Q_eitrigg_oldclan_4_TITLE = "旧债",
    MC_Q_eitrigg_oldclan_4_TEXT = "湿地中藏着氏族的宿敌。伊崔格去了结余下的恩怨。",
    MC_Q_taelan_crusade_1_TITLE = "十字军之子",
    MC_Q_taelan_crusade_1_TEXT = "泰兰在提瑞斯法的血色十字军中长大。",
    MC_Q_taelan_crusade_2_TITLE = "疑虑",
    MC_Q_taelan_crusade_2_TEXT = "十字军以圣光之名所做之事，已让他无法认同。",
    MC_Q_taelan_crusade_3_TITLE = "神圣之地",
    MC_Q_taelan_crusade_3_TEXT = "泰兰所立之处，大地为圣光燃烧。",
    MC_Q_taelan_crusade_4_TITLE = "追随父亲的足迹",
    MC_Q_taelan_crusade_4_TEXT = "提里奥之子前往希尔斯布莱德，那是他父亲流放的起点。",
    MC_Q_saurfang_warrior_1_TITLE = "老战士",
    MC_Q_saurfang_warrior_1_TEXT = "萨鲁法尔经历的战争，比大多数兽人见过的冬天还多。",
    MC_Q_saurfang_warrior_2_TITLE = "加拉克劫掠者",
    MC_Q_saurfang_warrior_2_TEXT = "加拉克半人马在千针石林劫掠部落的商队。",
    MC_Q_saurfang_warrior_3_TITLE = "复仇",
    MC_Q_saurfang_warrior_3_TEXT = "挨下的每一击都要加倍奉还。萨鲁法尔不知道别的方式。",
    MC_Q_saurfang_warrior_4_TITLE = "高地",
    MC_Q_saurfang_warrior_4_TEXT = "阿拉希高地上有古老的力量在苏醒。萨鲁法尔将直面它，绝不倒下。",
    MC_Q_windsor_marshal_1_TITLE = "暴风城元帅",
    MC_Q_windsor_marshal_1_TEXT = "温德索尔元帅率领暴风城的士兵进入奥特兰克山脉。",
    MC_Q_windsor_marshal_2_TITLE = "辛迪加",
    MC_Q_windsor_marshal_2_TEXT = "奥特兰克的没落贵族如今统领着一帮盗贼。温德索尔要将其击溃。",
    MC_Q_windsor_marshal_3_TITLE = "山中的食人魔",
    MC_Q_windsor_marshal_3_TEXT = "食人魔氏族占据着山口。元帅需要打通它们。",
    MC_Q_windsor_marshal_4_TITLE = "进军荒芜之地",
    MC_Q_windsor_marshal_4_TEXT = "荒芜之地中一位古老的守护者正在苏醒。温德索尔将直面它，屹立不倒。",
    MC_Q_rexxar_wild_1_TITLE = "米莎的狩猎",
    MC_Q_rexxar_wild_1_TEXT = "雷克萨和他的熊米莎猎杀一切威胁荒野之物。",
    MC_Q_rexxar_wild_2_TITLE = "石爪山的伤痕",
    MC_Q_rexxar_wild_2_TEXT = "风险投资公司在砍伐石爪山的森林。雷克萨亲自前往。",
    MC_Q_rexxar_wild_3_TITLE = "熊与兽王",
    MC_Q_rexxar_wild_3_TEXT = "雷克萨指向哪里，米莎就攻向哪里。让他们多多出击。",
    MC_Q_rexxar_wild_4_TITLE = "丛林之王",
    MC_Q_rexxar_wild_4_TEXT = "荆棘谷的巨豹统治着丛林。雷克萨将屹立着与它对决。",
    MC_Q_sylvanas_forsaken_1_TITLE = "黑暗女王",
    MC_Q_sylvanas_forsaken_1_TEXT = "希尔瓦娜斯从提瑞斯法领导被遗忘者，摆脱了巫妖王的意志。",
    MC_Q_sylvanas_forsaken_2_TITLE = "银松森林的狼人",
    MC_Q_sylvanas_forsaken_2_TEXT = "狼人在银松森林中游荡。黑暗女王要肃清她的边境。",
    MC_Q_sylvanas_forsaken_3_TITLE = "阿鲁高的愚行",
    MC_Q_sylvanas_forsaken_3_TEXT = "召唤狼人的大法师躲在他的城堡里。希尔瓦娜斯将直面他，绝不倒下。",
    MC_Q_sylvanas_forsaken_4_TITLE = "凋零之箭",
    MC_Q_sylvanas_forsaken_4_TEXT = "女妖之箭所及之处尽皆腐朽。让它们飞吧。",
    MC_Q_voljin_darkspear_1_TITLE = "暗矛之家",
    MC_Q_voljin_darkspear_1_TEXT = "沃金的部族在杜隆塔尔找到了家园，它必须保持安宁。",
    MC_Q_voljin_darkspear_2_TITLE = "巨魔对巨魔",
    MC_Q_voljin_darkspear_2_TEXT = "并非所有巨魔部族都追随部落。沃金回击那些威胁族人的人。",
    MC_Q_voljin_darkspear_3_TITLE = "暗影猎手的妖术",
    MC_Q_voljin_darkspear_3_TEXT = "暗影猎手能把敌人变成青蛙。让沃金展示他的技艺。",
    MC_Q_voljin_darkspear_4_TITLE = "古老的丛林",
    MC_Q_voljin_darkspear_4_TEXT = "巨魔来自荆棘谷。沃金重返故地，屹立着面对那里的主宰。",
    MC_Q_renzik_shiv_1_TITLE = "刀锋的地盘",
    MC_Q_renzik_shiv_1_TEXT = "伦兹克在艾尔文的阴影中为军情七处效力。",
    MC_Q_renzik_shiv_2_TITLE = "红头巾",
    MC_Q_renzik_shiv_2_TEXT = "军情七处想要迪菲亚的计划，伦兹克悄无声息地拿到手。",
    MC_Q_renzik_shiv_3_TITLE = "卑鄙伎俩",
    MC_Q_renzik_shiv_3_TEXT = "一记戳眼能让许多战斗在开始前就结束。",
    MC_Q_renzik_shiv_4_TITLE = "守夜",
    MC_Q_renzik_shiv_4_TEXT = "某个缝合之物在暮色森林的路上游荡。伦兹克会看着它倒下然后离开。",
    MC_Q_renzik_loose_ends_1_TITLE = "收尾工作",
    MC_Q_renzik_loose_ends_1_TEXT = "范克里夫已经倒下，但军情七处要确保矿井里没有留下任何东西。伦兹克亲自下去。",
    MC_Q_renzik_loose_ends_2_TITLE = "刀锋之刃",
    MC_Q_renzik_loose_ends_2_TEXT = "熟能生锋。伦兹克让他的刀始终锋利。",
    MC_Q_jorach_ravenholdt_1_TITLE = "拉文霍德的召唤",
    MC_Q_jorach_ravenholdt_1_TEXT = "乔拉赫·拉文霍德勋爵在奥特兰克的山丘中统领刺客公会。",
    MC_Q_jorach_ravenholdt_2_TITLE = "盗贼与刺客",
    MC_Q_jorach_ravenholdt_2_TEXT = "辛迪加败坏了盗贼的名声。拉文霍德来解决此事。",
    MC_Q_jorach_ravenholdt_3_TITLE = "肾击",
    MC_Q_jorach_ravenholdt_3_TEXT = "刺客只需要一瞬间，肾击能争取到它。",
    MC_Q_jorach_ravenholdt_4_TITLE = "最后的贵族",
    MC_Q_jorach_ravenholdt_4_TEXT = "奥特兰克最后的王位觊觎者藏在废墟中。乔拉赫将了结他并安然离开。",
    MC_Q_natpagle_fishing_1_TITLE = "钓鱼去了",
    MC_Q_natpagle_fishing_1_TEXT = "纳特·帕格只想在尘泥沼泽安静地钓鱼。",
    MC_Q_natpagle_fishing_2_TITLE = "啪嗒的大嘴",
    MC_Q_natpagle_fishing_2_TEXT = "鳄鱼总是偷走他的渔获。纳特受够了。",
    MC_Q_natpagle_fishing_3_TITLE = "新鲜渔获",
    MC_Q_natpagle_fishing_3_TEXT = "一条鲜鱼几乎能解决一切。纳特分享他的渔获。",
    MC_Q_natpagle_fishing_4_TITLE = "鱼人威胁",
    MC_Q_natpagle_fishing_4_TEXT = "有水的地方就有鱼人。有鱼人的地方，鱼就跑光了。",
    MC_Q_jaina_theramore_1_TITLE = "大法师的岛屿",
    MC_Q_jaina_theramore_1_TEXT = "吉安娜在泽弗拉斯岛上守护着古老的魔法。",
    MC_Q_jaina_theramore_2_TITLE = "寒冰箭",
    MC_Q_jaina_theramore_2_TEXT = "很少有法师能像吉安娜一样施放冰霜。展示一下吧。",
    MC_Q_jaina_theramore_3_TITLE = "达拉然的阴影",
    MC_Q_jaina_theramore_3_TEXT = "达拉然的学徒在银松森林兴风作浪。吉安娜前去查明原因。",
    MC_Q_jaina_theramore_4_TITLE = "黑龙",
    MC_Q_jaina_theramore_4_TEXT = "奥妮克希亚化身贵族藏在塞拉摩附近。吉安娜将直面她，绝不倒下。",
    MC_Q_thrall_warchief_1_TITLE = "部落酋长",
    MC_Q_thrall_warchief_1_TEXT = "萨尔在杜隆塔尔建起了奥格瑞玛。他守护着族人建立的一切。",
    MC_Q_thrall_warchief_2_TITLE = "风暴之声",
    MC_Q_thrall_warchief_2_TEXT = "元素回应着酋长。让闪电在敌人之间跳跃。",
    MC_Q_thrall_warchief_3_TITLE = "旧日的枷锁",
    MC_Q_thrall_warchief_3_TEXT = "龙喉兽人仍在用锁链束缚红龙。萨尔明白锁链意味着什么。",
    MC_Q_thrall_warchief_4_TITLE = "格瑞姆巴托的阴影",
    MC_Q_thrall_warchief_4_TEXT = "龙喉首领占据着湿地。萨尔将击败他并屹立不倒。",
    MC_Q_tyrande_elune_1_TITLE = "大祭司",
    MC_Q_tyrande_elune_1_TEXT = "泰兰德在艾露恩的光辉下，从泰达希尔领导暗夜精灵。",
    MC_Q_tyrande_elune_2_TITLE = "艾露恩的慈悲",
    MC_Q_tyrande_elune_2_TEXT = "女神通过她的祭司施予治愈。让她多多治疗吧。",
    MC_Q_tyrande_elune_3_TITLE = "黑暗的海岸",
    MC_Q_tyrande_elune_3_TEXT = "腐化沿着黑海岸蔓延。泰兰德亲自前往。",
    MC_Q_tyrande_elune_4_TITLE = "萨特的污染",
    MC_Q_tyrande_elune_4_TEXT = "萨特曾是暗夜精灵，至今仍在毒害森林。艾露恩的祭司予以回应。",
    MC_Q_magatha_grimtotem_1_TITLE = "老巫婆",
    MC_Q_magatha_grimtotem_1_TEXT = "玛加萨从长者高地注视着莫高雷，她记得一切。",
    MC_Q_magatha_grimtotem_2_TITLE = "氏族之事",
    MC_Q_magatha_grimtotem_2_TEXT = "并非所有恐怖图腾都服从族长。玛加萨会处理那些不听话的。",
    MC_Q_magatha_grimtotem_3_TITLE = "虚弱之敌",
    MC_Q_magatha_grimtotem_3_TEXT = "虚弱的敌人就是被打败的敌人。玛加萨的诅咒会确保这一点。",
    MC_Q_magatha_grimtotem_4_TITLE = "石林",
    MC_Q_magatha_grimtotem_4_TEXT = "石林之中，一股古老的力量变得过于嚣张。玛加萨将挫其锐气并屹立不倒。",
    MC_Q_magatha_whispers_1_TITLE = "洞穴中的低语",
    MC_Q_magatha_whispers_1_TEXT = "沃尔丹倒下后，玛加萨听见洞穴低语着力量的秘密。她前去聆听。",
    MC_Q_magatha_whispers_2_TITLE = "尖牙的秘密",
    MC_Q_magatha_whispers_2_TEXT = "尖牙德鲁伊懂得扭曲梦境。玛加萨想把这份知识据为己有。",
    MC_Q_fandral_staghelm_1_TITLE = "大德鲁伊的骄傲",
    MC_Q_fandral_staghelm_1_TEXT = "范达尔领导塞纳里奥议会，他要夺回凄凉之地的土地。",
    MC_Q_fandral_staghelm_2_TITLE = "月火术",
    MC_Q_fandral_staghelm_2_TEXT = "月光会灼烧伤害大地之人。",
    MC_Q_fandral_staghelm_3_TITLE = "萨特之灾",
    MC_Q_fandral_staghelm_3_TEXT = "萨特散播着军团的污染。大德鲁伊将把他们连根拔除。",
    MC_Q_fandral_staghelm_4_TITLE = "蔓生的菲拉斯",
    MC_Q_fandral_staghelm_4_TEXT = "菲拉斯的食人魔之王统治着上古精灵的废墟。范达尔将屹立着与他对决。",
    MC_Q_drekthar_frostwolf_1_TITLE = "霜狼长者",
    MC_Q_drekthar_frostwolf_1_TEXT = "霜狼的盲眼萨满德雷克塔尔守望着奥特兰克的山谷。",
    MC_Q_drekthar_frostwolf_2_TITLE = "北方的寒意",
    MC_Q_drekthar_frostwolf_2_TEXT = "冰霜之灵回应着老萨满。让它们咬下去吧。",
    MC_Q_drekthar_frostwolf_3_TITLE = "山口的食人魔",
    MC_Q_drekthar_frostwolf_3_TEXT = "食人魔劫掠霜狼的畜群。德雷克塔尔要他们滚开。",
    MC_Q_drekthar_frostwolf_4_TITLE = "辛特兰",
    MC_Q_drekthar_frostwolf_4_TEXT = "一名巨魔巫医用黑暗魔法统治着辛特兰。德雷克塔尔将直面他，绝不倒下。",
    MC_QUESTS_PARTY = "队伍中",
    MC_QUESTS_BENCH = "候补",
    MC_QUESTS_DONE = "已完成",
    MC_ZD_ragefire = "奥格瑞玛之下，穴居人和燃刃教派向烈火深处挖掘。%s在深处统领着他们。",
    MC_ZD_shadowfang = "大法师阿鲁高将狼人召入席瓦莱恩男爵的城堡。鬼魂与狼群在顶层守护着%s。",
    MC_ZD_blackfathom = "在艾露恩沉没的神殿中，暮光之锤效忠于%s。纳迦和远古野兽守卫着下行之路。",
    MC_ZD_stockade = "暴风城监狱的囚犯发动了暴乱。%s在牢房中领导着暴动。",
    MC_ZD_gnomeregan = "侏儒的都城遭到污染，被穴居人占领。叛徒%s在城市核心统治着这里。",
    MC_ZD_kraul = "贫瘠之地南部的荆棘迷宫深处聚集着野猪人。老巫婆%s掌控着剃刀沼泽的核心。",
    MC_QK_SEARINGBLADE = "燃刃教徒",
    MC_QK_TWILIGHT = "暮光之锤教徒",
    MC_QK_IRRADIATED = "辐射生物",
    MC_QK_RAZORFEN = "剃刀沼泽野猪人",
    MC_QUEST_UNLOCK_blackfathom_aquanis = "在黑暗深渊中唤出阿奎尼斯男爵",
    MC_Q_thrall_ragefire_1_TITLE = "奥格瑞玛之下的火焰",
    MC_Q_thrall_ragefire_1_TEXT = "巴扎兰已死，但燃刃教派仍藏在城下。萨尔亲自下去。",
    MC_Q_thrall_ragefire_2_TITLE = "净化怒焰",
    MC_Q_thrall_ragefire_2_TEXT = "每倒下一个教徒，部落都城中就少一个叛徒。",
    MC_Q_sylvanas_arugal_1_TITLE = "大法师的城堡",
    MC_Q_sylvanas_arugal_1_TEXT = "阿鲁高已死，但他的城堡仍在孕育狼人。黑暗女王要亲眼看看。",
    MC_Q_sylvanas_arugal_2_TITLE = "清除狼人",
    MC_Q_sylvanas_arugal_2_TEXT = "清除城堡中的狼人，不让任何一个到达被遗忘者的土地。",
    MC_Q_shandris_blackfathom_1_TITLE = "深渊男爵",
    MC_Q_shandris_blackfathom_1_TEXT = "暮光之锤在深渊中守护着一块深渊之石。打破他们的控制，被它束缚的水之领主就会现身。",
    MC_Q_windsor_stockade_1_TITLE = "监狱暴动",
    MC_Q_windsor_stockade_1_TEXT = "巴基尔·斯瑞德已经倒下，但牢房仍在骚动。元帅亲自恢复秩序。",
    MC_Q_windsor_stockade_2_TITLE = "铁窗之后",
    MC_Q_windsor_stockade_2_TEXT = "牢房中的每个迪菲亚都要回到他该待的地方。",
    MC_Q_magni_gnomeregan_1_TITLE = "盟友之城",
    MC_Q_magni_gnomeregan_1_TEXT = "瑟玛普拉格已经倒下，但诺莫瑞根远未得救。麦格尼与侏儒们一同深入。",
    MC_Q_magni_gnomeregan_2_TITLE = "被污染的大厅",
    MC_Q_magni_gnomeregan_2_TEXT = "辐射扭曲了穴居人和软泥。清理大厅，迎接侏儒归来。",
    MC_Q_cairne_kraul_1_TITLE = "荆棘迷宫",
    MC_Q_cairne_kraul_1_TEXT = "卡尔加已经倒下，但野猪人仍聚集在剃刀沼泽。凯恩进去要做个了断。",
    MC_Q_cairne_kraul_2_TITLE = "削减兽群",
    MC_Q_cairne_kraul_2_TEXT = "野猪人从这里袭击莫高雷。凯恩要看着他们的数量减少。",
    MC_A_taragaman_s = "火焰新星",
    MC_A_silverlaine_s = "暗影迷雾",
