    MC_Z_sm_cathedral = "血色修道院：大教堂",
    MC_ZD_sm_graveyard = "十字军在修道院后埋葬死者，但他们不得安息。%s守卫着墓穴。",
    MC_ZD_sm_library = "十字军的学者在图书馆里囤积禁忌知识。%s守护着其中的秘密。",
    MC_ZD_sm_armory = "十字军在军械库训练新兵。血色勇士%s等待着值得一战的对手。",
    MC_ZD_sm_cathedral = "莫格莱尼指挥官在大教堂率领十字军精锐。%s在祭坛前等候。",
    MC_ZD_downs = "天灾军团在野猪人的墓冢中找到了盟友。巫妖%s在深处统治着他们。",
    MC_ZD_uldaman = "穴居人和暗炉矮人在荒芜之地挖掘泰坦的宝库。在最深处，%s苏醒了。",
    MC_Q_tirion_monastery_1_TITLE = "血色之心",
    MC_Q_tirion_monastery_1_TEXT = "怀特迈恩已经倒下，但十字军仍占据着大教堂。提里奥要进去提醒他们圣光的真谛。",
    MC_Q_tirion_monastery_2_TITLE = "终结狂热",
    MC_Q_tirion_monastery_2_TEXT = "每倒下一个十字军，就少一个追猎无辜者的狂热分子。",
    MC_Q_jaina_doan_1_TITLE = "禁忌知识",
    MC_Q_jaina_doan_1_TEXT = "杜安已死，但图书馆中仍藏着十字军本不该拥有的魔法。吉安娜要亲眼看看。",
    MC_Q_jaina_doan_2_TITLE = "焚毁书页",
    MC_Q_jaina_doan_2_TEXT = "在守护者将这些秘密用来对付世界之前，清除图书馆中的他们。",
    MC_Q_saurfang_herod_1_TITLE = "血色勇士",
    MC_Q_saurfang_herod_1_TEXT = "赫洛德曾吹嘘没有兽人能抵挡他。萨鲁法尔要亲眼看看他的军械库。",
    MC_Q_saurfang_herod_2_TITLE = "溃散的军阵",
    MC_Q_saurfang_herod_2_TEXT = "在十字军自己的大厅里击溃他们的士兵。",
    MC_Q_benedictus_downs_1_TITLE = "带来圣光",
    MC_Q_benedictus_downs_1_TEXT = "亚门纳尔已经倒下，但天灾仍在墓冢中蠢动。大主教亲自将圣光带下去。",
    MC_Q_benedictus_downs_2_TITLE = "让死者安息",
    MC_Q_benedictus_downs_2_TEXT = "每一具再次倒下的复活尸体，都是一个重获安息的灵魂。",
    MC_Q_magni_uldaman_1_TITLE = "泰坦宝库",
    MC_Q_magni_uldaman_1_TEXT = "阿扎达斯再次沉睡，探险者协会想要奥达曼的秘密。麦格尼亲自带路。",
    MC_Q_magni_uldaman_2_TITLE = "清理挖掘场",
    MC_Q_magni_uldaman_2_TEXT = "石窟穴居人挤满了矮人想要研究的大厅。把他们赶出去。",
