    MC_ZD_zulfarrak = "在塔纳利斯的沙漠中，沙怒巨魔守护着他们的城市和圣池。%s在神庙台阶上统治着一切。",
    MC_ZD_maraudon = "凄凉之地地下，萨特污染着扎尔塔之魂徘徊的洞穴。%s在最深处等待。",
    MC_ZD_sunken = "阿塔莱在沉没的神庙中召唤血神哈卡，绿龙则在梦魇中守护着%s。",
    MC_ZD_brd = "黑石山深处是黑铁矮人的城市。%s在那里临朝，茉艾拉公主陪伴在侧。",
    MC_ZD_lbrs = "在黑铁矮人的城市之上，黑石兽人带着食人魔和巨魔占据着高塔。%s统领着他们。",
    MC_ZD_dm_east = "在埃德雷斯拉斯的废墟中，扭木的萨特腐化着森林。%s在扭曲的树木间等待。",
    MC_ZD_dm_west = "最后的上层精灵依靠他们束缚的恶魔汲取力量。%s不肯放手。",
    MC_ZD_dm_north = "戈多克食人魔占据了北区并加冕了国王。%s以最强的拳头统治。",
    MC_ZD_scholomance = "在凯尔达隆，诅咒神教在巴罗夫家族的古老墓穴中教授死灵法术。%s执掌学院。",
    MC_ZD_strat_live = "在斯坦索姆正门之后，血色十字军在%s的带领下抵抗天灾，而他伪装成了大十字军战士达索汉。",
    MC_ZD_strat_undead = "在焚毁之城的东半部，天灾的通灵塔拔地而起。%s在他的屠宰场中发号施令。",
    MC_QK_SANDFURY = "沙怒巨魔",
    MC_QK_ATALAI = "阿塔莱",
    MC_QK_HIGHBORNE = "上层精灵",
    MC_QUEST_UNLOCK_sunken_avatar = "在沉没的神庙中召唤哈卡的化身",
    MC_QUEST_UNLOCK_scholo_darkreaver = "在通灵学院唤起一名死亡骑士",
    MC_Q_rexxar_zulfarrak_1_TITLE = "沙怒之城",
    MC_Q_rexxar_zulfarrak_1_TEXT = "乌克兹已经倒下，但沙怒巨魔仍在袭击沙漠商队。雷克萨要进去终结他们的狩猎。",
    MC_Q_rexxar_zulfarrak_2_TITLE = "尘土与白骨",
    MC_Q_rexxar_zulfarrak_2_TEXT = "把沙怒巨魔赶出他们城市的街道。",
    MC_Q_fandral_maraudon_1_TITLE = "扎尔塔之墓",
    MC_Q_fandral_maraudon_1_TEXT = "瑟莱德丝已经倒下，但萨特仍在玷污玛拉顿。范达尔要深入净化洞穴。",
    MC_Q_fandral_maraudon_2_TITLE = "萨特之祸",
    MC_Q_fandral_maraudon_2_TEXT = "萨特污染了洞穴中的每一处泉水。追杀他们。",
    MC_Q_voljin_hakkar_1_TITLE = "血神",
    MC_Q_voljin_hakkar_1_TEXT = "阿塔莱试图将哈卡带入这个世界。摧毁这个教派，它的化身就会在神庙中现身。",
    MC_Q_magni_moira_1_TITLE = "掳走我女儿的人",
    MC_Q_magni_moira_1_TEXT = "索瑞森已死，茉艾拉的命运压在她父亲心头。麦格尼亲自进入黑铁之城。",
    MC_Q_magni_moira_2_TITLE = "铁怒卫队",
    MC_Q_magni_moira_2_TEXT = "击溃让茉艾拉远离家园的卫队。",
    MC_Q_eitrigg_spire_1_TITLE = "旧部族，新主人",
    MC_Q_eitrigg_spire_1_TEXT = "维姆萨拉克已经倒下，但黑石部族仍在为龙效力。艾特里格要亲眼看看他的旧部族。",
    MC_Q_eitrigg_spire_2_TITLE = "火印",
    MC_Q_eitrigg_spire_2_TEXT = "火印军团守卫着高塔。击溃他们的阵线。",
    MC_Q_hamuul_alzzin_1_TITLE = "扭木",
    MC_Q_hamuul_alzzin_1_TEXT = "奥兹恩已死，但扭木仍在扭曲。哈缪尔要进去治愈森林。",
    MC_Q_hamuul_alzzin_2_TITLE = "野性萨特",
    MC_Q_hamuul_alzzin_2_TEXT = "萨特在散播腐化。把他们赶走。",
    MC_Q_tyrande_highborne_1_TITLE = "最后的上层精灵",
    MC_Q_tyrande_highborne_1_TEXT = "托塞德林已经倒下。泰兰德前往那些曾因古老傲慢而毁灭她族人的大厅。",
    MC_Q_tyrande_highborne_2_TITLE = "让埃德雷斯拉斯安息",
    MC_Q_tyrande_highborne_2_TEXT = "解救仍在西区游荡的上层精灵。",
    MC_Q_rexxar_gordok_1_TITLE = "食人魔之血",
    MC_Q_rexxar_gordok_1_TEXT = "戈多克大王已经倒下。雷克萨本身就有一半食人魔血统，他想看看现在谁在领导戈多克。",
    MC_Q_rexxar_gordok_2_TITLE = "最强之拳",
    MC_Q_rexxar_gordok_2_TEXT = "在食人魔中，最强者为王。让他们看看谁才是。",
    MC_Q_tirion_darkreaver_1_TITLE = "死亡骑士",
    MC_Q_tirion_darkreaver_1_TEXT = "通灵学院为一位死亡骑士的回归复活死者。让足够多的亡灵安息，那名死亡骑士就会来找你。",
    MC_Q_taelan_balnazzar_1_TITLE = "我父亲的面孔",
    MC_Q_taelan_balnazzar_1_TEXT = "巴纳扎尔曾冒用泰兰之父的面孔领导十字军。如今他已死去，泰兰回到了斯坦索姆。",
    MC_Q_taelan_balnazzar_2_TITLE = "受骗的十字军",
    MC_Q_taelan_balnazzar_2_TEXT = "十字军仍在为谎言而战。结束这一切。",
    MC_Q_sylvanas_rivendare_1_TITLE = "男爵的屠宰场",
    MC_Q_sylvanas_rivendare_1_TEXT = "瑞文戴尔至死效忠巫妖王。希尔瓦娜斯进入他的城市，确保无人取而代之。",
    MC_Q_sylvanas_rivendare_2_TITLE = "终结天灾",
    MC_Q_sylvanas_rivendare_2_TEXT = "每倒下一个天灾仆从，巫妖王对东部的掌控就弱一分。",
